COMMON = "Use case: stylized-concept. Asset type: one ORIGINAL Heroes of Might and Magic III hero portrait SOURCE, square opaque newly painted 2D image, intended for58x64 large and48x32 small native portraits. The attached native Castle board is rendering/framing reference only: believable compact faces, tactile grainy hand-painted modeling, clear small eyes/mouth, rich varied original-game scenery. NOT its European costumes or architecture. Entire head/crown/hair inside image with modest top margin, close upper-shoulders, face center near(50%,43%), chin near68%, large face readable at58x64; no hands dominate. Three-quarter face with steady head tilt, normal portrait daylight from upper left. Region: deep jade/jungle green, ivory stepped Ixtali masonry, darkwood, muted gold/ochre, tiny justified turquoise/violet details. Inhabited pale stone arcology and natural foliage, not European castles, mosque domes, pagodas or a generic jungle hut. Matte painterly skin/fur/chitin/stone/cloth texture and tangible shadows, controlled highlights. No text, labels, border, UI, circular vignette, collage, empty/flat background, modern splash-art glamour, anime, exaggerated eyes, glossy3D, Blender, vector shapes, neon bloom, dramatic action pose or pixelation filters. "
ICON_COMMON = "Use case: stylized-concept. Asset type: one NEWLY HAND-PAINTED ORIGINAL Heroes of Might and Magic III specialty icon SOURCE; single square opaque image, intended44x44 and32x32 icon. Attached actual native specialty comparison is rendering/scale reference ONLY. Crisp tactile still-life/small allegory rendered as real objects in the classic game's painterly, slightly granular earthy material language. One large clearly readable subject, compact three-quarter depth, centered but organically composed, occupies80%of image, dark warm brown mottled stone/leather backing filling every pixel, upper-left soft light and real contact shadows. Ixtal jade/ivory/ochre muted accents; very restrained native spell glow only where asked. No portrait substitution, no labels/numbers/letters, frame, border, flat vector emblem, UI pictogram, geometric diagram, shiny3D, flat colored cutout, neon, bloom or modern app icon. No copied original icon pixels. "

def jobs():
    rows = []
    for key, detail in PORTRAITS.items():
        folder = BASE / key
        folder.mkdir(parents=True, exist_ok=True)
        for kind, prompt, name in (("portrait", COMMON + detail, "generation-request.json"),
                                    ("specialty", ICON_COMMON + ICON_SUBJECTS[key], "specialty-generation-request.json")):
            request = {"id":key,"kind":kind,"provider":"OpenAI built-in imagegen","model":"not exposed",
                       "prompt":prompt,"status":"request-authored","native_sizes": [[58,64],[48,32]] if kind=="portrait" else [[44,44],[32,32]],
                       "identity_boundary":"Established official champion identity reference; newly painted rendering" if key in ("qiyana","nidalee","neeko","milio","skarner","malphite","zyra") else "Original supporting-person appearance interpretation; source-prose cues retained, no authenticated exact canonical face claimed"}
            path = folder / name
            if not path.exists():
                path.write_text(json.dumps(request,indent=2,ensure_ascii=False)+"\n",encoding="utf-8")
            rows.append(request)
    return rows

if __name__ == "__main__":
    print("Prepared",len(jobs()),"individual built-in-imagegen requests; no generation executed by script.")
